import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(n, d):
    assert n % d == 0, f"{n} is not divisible by {d}"
    return n // d


# ---------------------------------------------------------------------------
# Autograd-aware communication primitives
# ---------------------------------------------------------------------------

def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


def _split_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunk = _divide(x.size(-1), ws)
    return x.narrow(-1, _rank() * chunk, chunk).contiguous()


def _gather_last(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad.clone())


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x.clone())

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: take local chunk of last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: take local chunk."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last(grad)


# ---------------------------------------------------------------------------
# Layers
# ---------------------------------------------------------------------------

class ColumnParallelLinear(nn.Module):
    """Y = X A^T + b, with A (out_features x in_features) split along the
    output dimension. Outputs are all-gathered along the last dimension."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.output_size_per_partition = _divide(out_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        start = self.rank * self.output_size_per_partition
        end = start + self.output_size_per_partition
        self.weight = nn.Parameter(master_weight[start:end, :].detach().clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.output_size_per_partition,
                    dtype=self.weight.dtype,
                    device=self.weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x = _CopyToParallelRegion.apply(x)
        out = F.linear(x, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out)


class RowParallelLinear(nn.Module):
    """Y = X A^T + b, with A (out_features x in_features) split along the
    input dimension. Partial outputs are all-reduced (summed); bias is full
    on every rank and added after the reduction."""

    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.input_size_per_partition = _divide(in_features, self.world_size)

        master_weight = torch.as_tensor(master_weight)
        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight shape {tuple(master_weight.shape)} != "
            f"{(out_features, in_features)}"
        )
        start = self.rank * self.input_size_per_partition
        end = start + self.input_size_per_partition
        self.weight = nn.Parameter(master_weight[:, start:end].detach().clone().contiguous())

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(out_features, dtype=self.weight.dtype, device=self.weight.device)
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input or an already-partitioned input.
        if x.size(-1) == self.in_features:
            x = _ScatterToParallelRegion.apply(x)
        elif x.size(-1) != self.input_size_per_partition:
            raise ValueError(
                f"Input last dim {x.size(-1)} matches neither in_features "
                f"({self.in_features}) nor partition size "
                f"({self.input_size_per_partition})"
            )
        partial = F.linear(x, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
